WITH flattened AS (SELECT id, plan, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) t AS tier_value) SELECT id, effective_from, currency, tier_value, CASE WHEN currency RLIKE '^(USD|THB)$' THEN 'GROUP_B' WHEN currency RLIKE '^(EUR)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS currency_zone FROM flattened ORDER BY currency_zone DESC NULLS LAST;
